import pathlib,json,hashlib
R=pathlib.Path(__file__).resolve().parents[1];FIRST=R.parent
for batch,base in [(1,FIRST),(2,FIRST/'Batch02')]:
 checks=[]
 for e in json.loads((base/'delivery_manifest.json').read_text())['files']:
  p=base/e['path'];h=hashlib.sha256(p.read_bytes()).hexdigest();checks.append({'path':e['path'],'sha256':h,'matches_delivery':h==e['sha256']})
 assert all(e['matches_delivery'] for e in checks)
 (R/f'Validation/batch{batch:02d}_freeze_before.json').write_text(json.dumps(checks,indent=2))
def sock(i,p,n):return {'id':i,'position_m':p,'outward_normal':n,'role':'fluid_port','outer_flange_radius_m':.375,'bore_radius_m':.21}
entries=[('SM_NPP_Pipe_Straight_4m_A','pipe',[0,-.375,-.375],[4,.375,.375],[sock('in',[0,0,0],[-1,0,0]),sock('out',[4,0,0],[1,0,0])]),('SM_NPP_Pipe_Elbow90_R1_A','elbow',[0,-.375,-.375],[1.375,1,.375],[sock('in',[0,0,0],[-1,0,0]),sock('out',[1,1,0],[0,1,0])]),('SM_NPP_Pipe_Tee_2m_A','pipe_tee',[0,-.375,-.375],[2,1,.375],[sock('in',[0,0,0],[-1,0,0]),sock('out',[2,0,0],[1,0,0]),sock('branch',[1,1,0],[0,1,0])]),('SM_NPP_Valve_1m_A','valve',[0,-.4,-.375],[1,.4,1.125],[sock('in',[0,0,0],[-1,0,0]),sock('out',[1,0,0],[1,0,0])]),('SM_NPP_PumpSkid_4x2_A','pump',[0,-1,0],[4,1,2],[sock('in',[0,0,1],[-1,0,0]),sock('out',[1.5,1,1],[0,1,0])])]
M={'project':'NPP / Sector K-17','batch':3,'scope':'04_PUMP zone replacement in original site coordinates, with five new pipe/equipment assets. Other seven zones remain graybox.','primary_module_m':4,'grid_m':.25,'assets':[]}
for id,kind,mn,mx,ss in entries:
 p=R/'Assets'/id;p.mkdir(exist_ok=True)
 sp={'asset_id':id,'builder':kind,'units':'meters','origin_m':[0,0,0],'bounds_min':mn,'bounds_max':mx,'dimensions':[b-a for a,b in zip(mn,mx)],'grid_size':.25,'connection_sockets':ss,'pipe_outer_radius_m':.265,'pipe_inner_radius_m':.21,'flange_radius_m':.375,'flange_depth_m':.12,'coordinate_convention':{'up':'+Z','front_camera':'-Y','right_camera':'+X','top_camera':'+Z'},'material_level':'Basic PBR painted teal / graphite / galvanized / safety yellow. No final weathering.','reference_views':['front.png','right.png','top.png'],'collision_policy':'Closed convex gameplay proxies. Internal pipe bore need not be traversable.','design_limit':'Original environment art, not a certified engineering or reactor-operating design.'}
 if kind=='elbow':sp['centerline']={'bend_radius_m':1,'center_m':[0,1,0],'sweep_degrees':[-90,0]}
 if kind=='pump':sp['design']='Stylized horizontal centrifugal transfer pump and electric motor on a skid; two matching pipe ports. Actual pump internals not simulated.'
 (p/'spec.json').write_text(json.dumps(sp,indent=2));M['assets'].append({'asset_id':id,'kind':kind,'path':str(p.relative_to(R))})
(R/'manifest.json').write_text(json.dumps(M,indent=2))
region={'zone_id':'04_PUMP','source_layout':'../Blockout/layout_spec.json','bounds_min_m':[-8,-28,0],'bounds_max_m':[24,-4,8],'footprint_m':[32,24],'function':'Pump and water-treatment service yard with a two-level maintenance/control annex','replacement':'Remove original 04_PUMP box and its label in a COPY of the site; keep seven other zone placeholders','building':{'floor_x':[-7.75,-3.75],'floor_y':[-28,-24,-20,-16,-12,-8],'upper_floor_z':4,'roof_bottom_z':7.745,'roof_seating_note':'5 mm seating offset avoids coplanar roof/wall caps; wall top remains 8 m.','east_wall_x':.25,'upper_door_y':-6,'ground_east_door_y':-26},'process':{'pump_origins':[[7,-20,1],[7,-14,1],[7,-8,1]],'plinth_height_m':1,'inlet_header_x':1,'return_header_x':15.5,'pipe_centerline_z':2,'bore_radius_m':.21,'pipe_radius_m':.265,'saddle_fit':'Batch01 inner saddle radius 0.265 m; pipe lower tangent seats at 1.735 m','header_endpoints':'Four labeled blind-flanged reserve connections, no operational fluid simulation'},'routes':{'ground':'East service lane X=20.25..24 plus 2.5 m south cross-route X=0.5..24, Y=-28..-25.5; secondary spaces between pump rows','elevated':'Z=4, east wall door at (0.25,-6), four straight modules across the north, a 90-degree corner and two east-side straight modules to two stair flights','nominal_width_m':2,'conservative_catwalk_clearance_m':1.75,'south_road_approach':{'floor_tiles':[[20,-40,0],[20,-36,0],[20,-32,0]],'width_m':4,'length_m':12,'connects_to_original_road_y':-44},'north_global_elevated_link':'Not built in this batch; access uses the east stair and ground road'},'reuses':{'batch01':['straight','corner','stairs','column','pipe_support'],'batch02':['solid_wall','door_wall','window_wall','floor','roof','column_head']},'quality_boundary':'One realized functional zone in an otherwise graybox site. Basic PBR. UE traversal, final surface art and whole-map completion remain pending.'}
(R/'Region/zone_spec.json').write_text(json.dumps(region,indent=2));print('BATCH03_SPECS_READY')
